function pickLang() {
  try { const s = localStorage.getItem('lang'); if (s && LANGS.some(l => l[0] === JSON.parse(s))) return JSON.parse(s); } catch {}
  const nav = (navigator.language || 'tr').slice(0, 2).toLowerCase();
  return LANGS.some(l => l[0] === nav) ? nav : 'tr';
}
let LANG = pickLang();
const LANG_IDX = () => LANGS.findIndex(l => l[0] === LANG);
// Kurdish date names are missing in some browsers; fall back to Turkish formats there
const LOCALE = () => {
  const loc = LANGS[LANG_IDX()][2];
  try { return Intl.DateTimeFormat.supportedLocalesOf([loc]).length ? loc : 'tr-TR'; } catch { return 'tr-TR'; }
};
function t(key, ...args) {
  const row = I18N[key];
  if (!row) return /^(n|role)\./.test(key) ? key.replace(/^\w+\./, '') : key;
  const parts = row.split('|');
  return (parts[LANG_IDX()] || parts[0]).replace(/\{(\d)\}/g, (_, i) => args[i] ?? '');
}
